    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, q;
    std::cin >> n >> q;

    // p[i] is the sum of the first i values, so p[0] is 0.
    std::vector<long long> p(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        int x;
        std::cin >> x;
        p[i + 1] = p[i] + x;
    }

    for (int i = 0; i < q; ++i) {
        int l, r;
        std::cin >> l >> r;
        std::cout << p[r] - p[l] << '\n';
    }
}

